function App() {
  const [name, setName] = useState('');
  const [greeting, setGreeting] = useState('');
  const handleSubmit = (e) => {
    e.preventDefault();
    setGreeting(name ? 'Hello, ' + name + '!' : 'Please enter a name.');
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <form onSubmit={handleSubmit}>
        <input
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Your name"
        />
        <button type="submit" style={{ marginLeft: 8 }}>Greet</button>
        <button type="button" onClick={() => { setName(''); setGreeting(''); }} style={{ marginLeft: 8 }}>Clear</button>
      </form>
      <p>{greeting}</p>
    </div>
  );
}

function App() {
  const [items] = useState([{ id: 1, label: 'Apples' }, { id: 2, label: 'Bananas' }]);
  const [selected, setSelected] = useState(null);
  const [log, setLog] = useState('');
  const selectRow = (id) => setSelected(id);
  const deleteRow = (e, id) => {
    e.stopPropagation();
    setLog('Delete clicked for #' + id + ' (row not selected)');
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {items.map((it) => (
          <li
            key={it.id}
            onClick={() => selectRow(it.id)}
            style={{ padding: 8, cursor: 'pointer', background: selected === it.id ? '#dde' : '#f4f4f4', marginBottom: 4 }}
          >
            {it.label}
            <button onClick={(e) => deleteRow(e, it.id)} style={{ marginLeft: 12 }}>Delete</button>
          </li>
        ))}
      </ul>
      <p>Selected: {selected ?? 'none'}</p>
      <p>{log}</p>
    </div>
  );
}

