function App() {
  const [count, setCount] = useState(0);
  const handleLike = () => setCount((c) => c + 1);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={handleLike}>Like ({count})</button>
    </div>
  );
}
